  Vector.count x (xs.flatMap f) = (Vector.map (Vector.count x ∘ f) xs).sum

theorem Vector.countP_flatMap.{u_1, u_2} {α : Type u_2} {β : Type u_1} {n m : ℕ} {p : β → Bool}
  {xs : Vector α n} {f : α → Vector β m} :
  Vector.countP p (xs.flatMap f) = (Vector.map (Vector.countP p ∘ f) xs).sum

theorem Vector.getElem?_zipWith'.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3} {n✝ : ℕ}
  {as : Vector α n✝} {bs : Vector β n✝} {f : α → β → γ} {i : ℕ} :
  (Vector.zipWith f as bs)[i]? = (Option.map f as[i]?).bind fun g => Option.map g bs[i]?

theorem Vector.zipWith_replicate.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {α✝ : Type u_3}
  {f : α → β → α✝} {a : α} {b : β} {n : ℕ} :
  Vector.zipWith f (Vector.replicate n a) (Vector.replicate n b) = Vector.replicate n (f a b)

theorem Vector.zipWith_append.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3} {n m : ℕ}
  {f : α → β → γ} {as : Vector α n} {as' : Vector α m} {bs : Vector β n} {bs' : Vector β m} :
  Vector.zipWith f (as ++ as') (bs ++ bs') = Vector.zipWith f as bs ++ Vector.zipWith f as' bs'

theorem Vector.zipWith_map_right.{u_1, u_2, u_3, u_4} {α : Type u_1} {n : ℕ} {β : Type u_2} {β' : Type u_3}
  {γ : Type u_4} {as : Vector α n} {bs : Vector β n} {f : β → β'} {g : α → β' → γ} :
  Vector.zipWith g as (Vector.map f bs) = Vector.zipWith (fun a b => g a (f b)) as bs

theorem Vector.zipWith_map_left.{u_1, u_2, u_3, u_4} {α : Type u_1} {n : ℕ} {β : Type u_2} {α' : Type u_3}
  {γ : Type u_4} {as : Vector α n} {bs : Vector β n} {f : α → α'} {g : α' → β → γ} :
  Vector.zipWith g (Vector.map f as) bs = Vector.zipWith (fun a b => g (f a) b) as bs

theorem Vector.zipWith_foldr_eq_zip_foldr.{u_1, u_2, u_3, u_4} {α : Type u_1} {β : Type u_2} {γ : Type u_3}
  {δ : Type u_4} {n✝ : ℕ} {as : Vector α n✝} {bs : Vector β n✝} {g : γ → δ → δ} {f : α → β → γ}
  {i : δ} :
  Vector.foldr g i (Vector.zipWith f as bs) =
    Vector.foldr (fun p r => g (f p.1 p.2) r) i (as.zip bs)

theorem Vector.zip_map_right.{u_1, u_2, u_3} {β : Type u_1} {γ : Type u_2} {α : Type u_3} {n : ℕ}
  {f : β → γ} {as : Vector α n} {bs : Vector β n} :
  as.zip (Vector.map f bs) = Vector.map (Prod.map id f) (as.zip bs)

theorem Vector.getElem?_zipWith_eq_some.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3} {n : ℕ}
  {f : α → β → γ} {as : Vector α n} {bs : Vector β n} {z : γ} {i : ℕ} :
  (Vector.zipWith f as bs)[i]? = some z ↔ ∃ x y, as[i]? = some x ∧ bs[i]? = some y ∧ f x y = z

theorem Vector.map_zip_eq_zipWith.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3} {n : ℕ}
  {f : α × β → γ} {as : Vector α n} {bs : Vector β n} :
  Vector.map f (as.zip bs) = Vector.zipWith (Function.curry f) as bs

theorem Vector.zipWith_comm.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3} {n : ℕ}
  {f : α → β → γ} {as : Vector α n} {bs : Vector β n} :
  Vector.zipWith f as bs = Vector.zipWith (fun b a => f a b) bs as

theorem Vector.zipWith_foldl_eq_zip_foldl.{u_1, u_2, u_3, u_4} {α : Type u_1} {β : Type u_2} {γ : Type u_3}
  {δ : Type u_4} {n✝ : ℕ} {as : Vector α n✝} {bs : Vector β n✝} {g : δ → γ → δ} {f : α → β → γ}
  {i : δ} :
  Vector.foldl g i (Vector.zipWith f as bs) =
    Vector.foldl (fun r p => g r (f p.1 p.2)) i (as.zip bs)

theorem Vector.map_uncurry_zip_eq_zipWith.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3}
  {n : ℕ} {f : α → β → γ} {as : Vector α n} {bs : Vector β n} :
  Vector.map (Function.uncurry f) (as.zip bs) = Vector.zipWith f as bs

theorem Vector.zip_map'.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3} {n : ℕ} {f : α → β}
  {g : α → γ} {xs : Vector α n} :
  (Vector.map f xs).zip (Vector.map g xs) = Vector.map (fun a => (f a, g a)) xs

theorem Vector.getElem?_zip_eq_some.{u_1, u_2} {α : Type u_1} {n : ℕ} {β : Type u_2} {as : Vector α n}
  {bs : Vector β n} {z : α × β} {i : ℕ} :
  (as.zip bs)[i]? = some z ↔ as[i]? = some z.1 ∧ bs[i]? = some z.2

theorem Vector.reverse_zipWith.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3} {n : ℕ}
  {f : α → β → γ} {as : Vector α n} {bs : Vector β n} :
  (Vector.zipWith f as bs).reverse = Vector.zipWith f as.reverse bs.reverse

theorem Vector.extract_zipWith.{u_1, u_2, u_3} {α✝ : Type u_1} {α✝¹ : Type u_2} {α✝² : Type u_3}
  {f : α✝ → α✝¹ → α✝²} {n✝ : ℕ} {as : Vector α✝ n✝} {bs : Vector α✝¹ n✝} {i j : ℕ} :
  (Vector.zipWith f as bs).extract i j = Vector.zipWith f (as.extract i j) (bs.extract i j)

theorem Vector.zip_map.{u_1, u_2, u_3, u_4} {α : Type u_1} {γ : Type u_2} {β : Type u_3} {δ : Type u_4}
  {n : ℕ} {f : α → γ} {g : β → δ} {as : Vector α n} {bs : Vector β n} :
  (Vector.map f as).zip (Vector.map g bs) = Vector.map (Prod.map f g) (as.zip bs)

theorem Vector.zip_of_prod.{u_1, u_2} {α : Type u_1} {n : ℕ} {β : Type u_2} {as : Vector α n}
  {bs : Vector β n} {xs : Vector (α × β) n} (hl : Vector.map Prod.fst xs = as)
  (hr : Vector.map Prod.snd xs = bs) : xs = as.zip bs

theorem Vector.zip_map_left.{u_1, u_2, u_3} {α : Type u_1} {γ : Type u_2} {n : ℕ} {β : Type u_3} {f : α → γ}
  {as : Vector α n} {bs : Vector β n} :
  (Vector.map f as).zip bs = Vector.map (Prod.map f id) (as.zip bs)

theorem Vector.zipWith_comm_of_comm.{u_1, u_2} {α : Type u_1} {β : Type u_2} {n : ℕ} {f : α → α → β}
  (comm : ∀ (x y : α), f x y = f y x) {xs ys : Vector α n} :
  Vector.zipWith f xs ys = Vector.zipWith f ys xs

theorem Vector.map_zipWith.{u_1, u_2, u_3, u_4} {α : Type u_1} {β : Type u_2} {γ : Type u_3} {n : ℕ}
  {δ : Type u_4} {f : α → β} {g : γ → δ → α} {as : Vector γ n} {bs : Vector δ n} :
  Vector.map f (Vector.zipWith g as bs) = Vector.zipWith (fun x y => f (g x y)) as bs

theorem Vector.zip_append.{u_1, u_2} {α : Type u_1} {n : ℕ} {β : Type u_2} {m : ℕ} {as : Vector α n}
  {bs : Vector β n} {as' : Vector α m} {bs' : Vector β m} :
  (as ++ as').zip (bs ++ bs') = as.zip bs ++ as'.zip bs'

theorem Vector.take_zipWith.{u_1, u_2, u_3} {α✝ : Type u_1} {α✝¹ : Type u_2} {α✝² : Type u_3}
  {f : α✝ → α✝¹ → α✝²} {n✝ : ℕ} {as : Vector α✝ n✝} {bs : Vector α✝¹ n✝} {i : ℕ} :
  (Vector.zipWith f as bs).take i = Vector.zipWith f (as.take i) (bs.take i)

theorem Vector.zipWith_map.{u_1, u_2, u_3, u_4, u_5} {γ : Type u_1} {δ : Type u_2} {α : Type u_3}
  {β : Type u_4} {n : ℕ} {μ : Type u_5} {f : γ → δ → μ} {g : α → γ} {h : β → δ} {as : Vector α n}
  {bs : Vector β n} :
  Vector.zipWith f (Vector.map g as) (Vector.map h bs) =
    Vector.zipWith (fun a b => f (g a) (h b)) as bs

theorem Vector.mapM_map.{u_1, u_2, u_3, u_4} {m : Type u_1 → Type u_2} {α : Type u_3} {β : Type u_4}
  {γ : Type u_1} {n : ℕ} [Monad m] [LawfulMonad m] {f : α → β} {g : β → m γ} {xs : Vector α n} :
  Vector.mapM g (Vector.map f xs) = Vector.mapM (g ∘ f) xs

theorem Vector.mapM_pure.{u_1, u_2, u_3} {m : Type u_1 → Type u_2} {α : Type u_3} {n : ℕ} {β : Type u_1}
  [Monad m] [LawfulMonad m] {xs : Vector α n} (f : α → β) :
  Vector.mapM (fun x => pure (f x)) xs = pure (Vector.map f xs)

