  (h_2 : (b : β) → motive (ForInStep.done b)) : motive b✝

theorem Vector.forIn'_congr.{u_1, u_2, u_3} {m : Type u_1 → Type u_2} {α : Type u_3} {n : ℕ} {β : Type u_1}
  [Monad m] {xs ys : Vector α n} (w : xs = ys) {b b' : β} (hb : b = b')
  {f : (a' : α) → a' ∈ xs → β → m (ForInStep β)} {g : (a' : α) → a' ∈ ys → β → m (ForInStep β)}
  (h : ∀ (a : α) (m_1 : a ∈ ys) (b : β), f a ⋯ b = g a m_1 b) : forIn' xs b f = forIn' ys b' g

theorem Vector.foldrM_map.{u_1, u_2, u_3, u_4} {m : Type u_1 → Type u_2} {β₁ : Type u_3} {β₂ : Type u_4}
  {α : Type u_1} {n : ℕ} [Monad m] [LawfulMonad m] {f : β₁ → β₂} {g : β₂ → α → m α}
  {xs : Vector β₁ n} {init : α} :
  Vector.foldrM g init (Vector.map f xs) = Vector.foldrM (fun x y => g (f x) y) init xs

theorem Vector.forM_map.{u_1, u_2, u_3, u_4} {m : Type u_1 → Type u_2} {α : Type u_3} {n : ℕ} {β : Type u_4}
  [Monad m] [LawfulMonad m] {xs : Vector α n} {g : α → β} {f : β → m PUnit.{u_1 + 1}} :
  forM (Vector.map g xs) f = forM xs fun a => f (g a)

theorem Vector.findSomeM?_pure.{u_1, u_2, u_3} {m : Type u_1 → Type u_2} {α : Type u_3} {β : Type u_1}
  {n : ℕ} [Monad m] [LawfulMonad m] {f : α → Option β} {xs : Vector α n} :
  Vector.findSomeM? (fun x => pure (f x)) xs = pure (Vector.findSome? f xs)

theorem Vector.foldlM_map.{u_1, u_2, u_3, u_4} {m : Type u_1 → Type u_2} {β₁ : Type u_3} {β₂ : Type u_4}
  {α : Type u_1} {n : ℕ} [Monad m] {f : β₁ → β₂} {g : α → β₂ → m α} {xs : Vector β₁ n} {init : α} :
  Vector.foldlM g init (Vector.map f xs) = Vector.foldlM (fun x y => g x (f y)) init xs

theorem Vector.ofFnM_add.{u_1, u_2} {k : ℕ} {α : Type u_1} {n : ℕ} {m : Type u_1 → Type u_2} [Monad m]
  [LawfulMonad m] {f : Fin (n + k) → m α} :
  Vector.ofFnM f = do
    let as ← Vector.ofFnM fun i => f (Fin.castLE ⋯ i)
    let bs ← Vector.ofFnM fun i => f (Fin.natAdd n i)
    pure (as ++ bs)

theorem Vector.zipIdx_eq_append_iff.{u_1} {α : Type u_1} {n m : ℕ} {ys : Vector (α × ℕ) n}
  {zs : Vector (α × ℕ) m} {xs : Vector α (n + m)} {k : ℕ} :
  xs.zipIdx k = ys ++ zs ↔ ∃ ys' zs', xs = ys' ++ zs' ∧ ys = ys'.zipIdx k ∧ zs = zs'.zipIdx (k + n)

theorem Vector.set_eraseIdx_le.{u_1} {α : Type u_1} {n : ℕ} {xs : Vector α n} {i : ℕ} {w : i < n} {j : ℕ}
  {a : α} (h : i ≤ j) (hj : j < n - 1) :
  (xs.eraseIdx i w).set j a hj = (xs.set (j + 1) a ⋯).eraseIdx i w

theorem Vector.eraseIdx_append_of_length_le.{u_1} {α : Type u_1} {n m : ℕ} {xs : Vector α n} {k : ℕ}
  (hk : n ≤ k) (xs' : Vector α m) (h : k < n + m) :
  (xs ++ xs').eraseIdx k h = Vector.cast ⋯ (xs ++ xs'.eraseIdx (k - n) ⋯)

theorem Vector.eraseIdx_append_of_lt_size.{u_1} {α : Type u_1} {n m : ℕ} {xs : Vector α n} {k : ℕ}
  (hk : k < n) (xs' : Vector α m) (h : k < n + m) :
  (xs ++ xs').eraseIdx k h = Vector.cast ⋯ (xs.eraseIdx k hk ++ xs')

theorem Vector.eraseIdx_append.{u_1} {α : Type u_1} {n m : ℕ} {xs : Vector α n} {ys : Vector α m} {k : ℕ}
  (h : k < n + m) :
  (xs ++ ys).eraseIdx k h =
    if h' : k < n then Vector.cast ⋯ (xs.eraseIdx k h' ++ ys)
    else Vector.cast ⋯ (xs ++ ys.eraseIdx (k - n) ⋯)

theorem Vector.insertIdx_eraseIdx.{u} {α : Type u} {a : α} {n i j : ℕ} {as : Vector α n} (h₁ : i < n)
  (h₂ : j ≤ n - 1) :
  (as.eraseIdx i h₁).insertIdx j a h₂ =
    if h : i ≤ j then Vector.cast ⋯ ((as.insertIdx (j + 1) a ⋯).eraseIdx i ⋯)
    else Vector.cast ⋯ ((as.insertIdx j a ⋯).eraseIdx (i + 1) ⋯)

theorem Vector.Perm.extract.{u_1} {α : Type u_1} {n : ℕ} {xs ys : Vector α n} (h : xs.Perm ys) {lo hi : ℕ}
  (wlo : ∀ i < lo, xs[i]? = ys[i]?) (whi : ∀ (i : ℕ), hi ≤ i → xs[i]? = ys[i]?) :
  (xs.extract lo hi).Perm (ys.extract lo hi)

theorem Vector.findSome?_replicate_of_isNone.{u_1, u_2} {α✝ : Type u_1} {α✝¹ : Type u_2}
  {f : α✝ → Option α✝¹} {n : ℕ} {a : α✝} (h : (f a).isNone = true) :
  Vector.findSome? f (Vector.replicate n a) = none

theorem Vector.map_findSome?.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3} {n : ℕ}
  {f : α → Option β} {g : β → γ} {xs : Vector α n} :
  Option.map g (Vector.findSome? f xs) = Vector.findSome? (Option.map g ∘ f) xs

theorem Vector.get_find?_replicate {α : Type} {n : ℕ} {a : α} {p : α → Bool}
  (h : (Vector.find? p (Vector.replicate n a)).isSome = true) :
  (Vector.find? p (Vector.replicate n a)).get h = a

theorem Vector.findSome?_map.{u_1, u_2, u_3} {β : Type u_1} {γ : Type u_2} {n : ℕ} {α✝ : Type u_3}
  {p : γ → Option α✝} {f : β → γ} {xs : Vector β n} :
  Vector.findSome? p (Vector.map f xs) = Vector.findSome? (p ∘ f) xs

theorem Vector.findFinIdx?_subtype.{u_1} {α : Type u_1} {n : ℕ} {p : α → Prop} {xs : Vector { x // p x } n}
  {f : { x // p x } → Bool} {g : α → Bool} (hf : ∀ (x : α) (h : p x), f ⟨x, h⟩ = g x) :
  Vector.findFinIdx? f xs = Vector.findFinIdx? g xs.unattach

theorem Vector.findSomeRev?_push_of_isSome.{u_1, u_2} {α : Type u_1} {n : ℕ} {α✝ : Type u_2}
  {f : α → Option α✝} {a : α} {xs : Vector α n} {h : (f a).isSome = true} :
  Vector.findSomeRev? f (xs.push a) = f a

theorem Vector.findSome?_replicate_of_isSome.{u_1, u_2} {α✝ : Type u_1} {α✝¹ : Type u_2}
  {f : α✝ → Option α✝¹} {n : ℕ} {a : α✝} :
  (f a).isSome = true → Vector.findSome? f (Vector.replicate n a) = if n = 0 then none else f a

theorem Vector.find?_flatMap_eq_none_iff.{u_1} {α : Type u_1} {n : ℕ} {β : Type} {m : ℕ} {xs : Vector α n}
  {f : α → Vector β m} {p : β → Bool} :
  Vector.find? p (xs.flatMap f) = none ↔ ∀ x ∈ xs, ∀ y ∈ f x, (!p y) = true

theorem Vector.findSomeRev?_push_of_isNone.{u_1, u_2} {α : Type u_1} {n : ℕ} {α✝ : Type u_2}
  {f : α → Option α✝} {a : α} {xs : Vector α n} {h : (f a).isNone = true} :
  Vector.findSomeRev? f (xs.push a) = Vector.findSomeRev? f xs

theorem Vector.find?_flatMap.{u_1} {α : Type u_1} {n : ℕ} {β : Type} {m : ℕ} {xs : Vector α n}
  {f : α → Vector β m} {p : β → Bool} :
  Vector.find? p (xs.flatMap f) = Vector.findSome? (fun x => Vector.find? p (f x)) xs

theorem Vector.findSome?_append.{u_1, u_2} {α : Type u_1} {n₁ n₂ : ℕ} {α✝ : Type u_2} {f : α → Option α✝}
  {xs : Vector α n₁} {ys : Vector α n₂} :
  Vector.findSome? f (xs ++ ys) = (Vector.findSome? f xs).or (Vector.findSome? f ys)

